export type EventName = "order.created" | "refund.created" | "support.ticket";

export function recordEvent(name: EventName) {
  return { name, source: "unknown" };
}

edits.newText:
export type EventName = "order.created" | "refund.created" | "support.ticket";

export function recordEvent(name: EventName, source: string) {
  return { name, source };
}

